Конечно. Для создания «красивого» UI на C# без использования тяжелых сторонних библиотек (которые сложно настроить новичку) лучше всего подойдет **WPF**. Он позволяет использовать аппаратное ускорение, прозрачность, тени и современные шрифты, в отличие от старого WinForms.

Ниже представлен полный код современного калькулятора в стиле «Glassmorphism» (темная тема, акцентные цвета), а также батник для сборки и запуска.

### 1. Структура проекта

Создайте папку, например `BeautifulCalculator`, и поместите в нее файл `App.xaml.cs` (или просто `Program.cs`, но для WPF удобнее single-file подход через SDK-style проект).

Однако, чтобы вам было максимально просто запустить это **одним файлом** без установки Visual Studio (достаточно .NET SDK), мы сделаем это через `.csproj` и `MainWindow.xaml`.

#### Шаг 1: Создайте файл `BeautifulCalculator.csproj`
```xml
<Project Sdk="Microsoft.NET.Sdk">
  <PropertyGroup>
    <OutputType>WinExe</OutputType>
    <TargetFramework>net8.0-windows</TargetFramework>
    <UseWPF>true</UseWPF>
    <ImplicitUsings>enable</ImplicitUsings>
    <Nullable>enable</Nullable>
    <!-- Убираем стандартную рамку окна для кастомного дизайна -->
    <ApplicationIcon />
  </PropertyGroup>
</Project>
```

#### Шаг 2: Создайте файл `MainWindow.xaml`
Это разметка нашего красивого интерфейса.

```xml
<Window x:Class="BeautifulCalculator.MainWindow"
        xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation"
        xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml"
        Title="Calculator" Height="600" Width="400"
        WindowStartupLocation="CenterScreen"
        ResizeMode="NoResize"
        Background="Transparent"
        AllowsTransparency="True"
        WindowStyle="None"
        MouseLeftButtonDown="Window_MouseLeftButtonDown">

    <Border CornerRadius="20" Background="#FF1E1E1E" BorderBrush="#33FFFFFF" BorderThickness="1">
        <Grid Margin="20">
            <Grid.RowDefinitions>
                <RowDefinition Height="Auto"/> <!-- Drag Area / Close -->
                <RowDefinition Height="*"/>    <!-- Display -->
                <RowDefinition Height="4*"/>   <!-- Buttons -->
            </Grid.RowDefinitions>

            <!-- Кнопка закрытия (кастомная) -->
            <Button Content="✕" HorizontalAlignment="Right" VerticalAlignment="Top" 
                    FontSize="16" Foreground="#AAAAAA" Background="Transparent" 
                    BorderThickness="0" Cursor="Hand" Click="CloseButton_Click"/>

            <!-- Дисплей -->
            <StackPanel Grid.Row="1" VerticalAlignment="Bottom" HorizontalAlignment="Right" Margin="0,0,10,20">
                <TextBlock x:Name="HistoryText" Text="" FontSize="24" Foreground="#88FFFFFF" 
                           HorizontalAlignment="Right" FontWeight="Light"/>
                <TextBlock x:Name="DisplayText" Text="0" FontSize="64" Foreground="White" 
                           HorizontalAlignment="Right" FontWeight="SemiBold"/>
            </StackPanel>

            <!-- Сетка кнопок -->
            <UniformGrid Grid.Row="2" Columns="4" Rows="5">
                <!-- Ряд 1 -->
                <Button Style="{StaticResource CalcButton}" Content="C" Click="Clear_Click" Foreground="#FF6B6B"/>
                <Button Style="{StaticResource CalcButton}" Content="+/-" Click="Negate_Click"/>
                <Button Style="{StaticResource CalcButton}" Content="%" Click="Percent_Click"/>
                <Button Style="{StaticResource OperatorButton}" Content="÷" Click="Operator_Click" Tag="/"/>

                <!-- Ряд 2 -->
                <Button Style="{StaticResource CalcButton}" Content="7" Click="Number_Click"/>
                <Button Style="{StaticResource CalcButton}" Content="8" Click="Number_Click"/>
                <Button Style="{StaticResource CalcButton}" Content="9" Click="Number_Click"/>
                <Button Style="{StaticResource OperatorButton}" Content="×" Click="Operator_Click" Tag="*"/>

                <!-- Ряд 3 -->
                <Button Style="{StaticResource CalcButton}" Content="4" Click="Number_Click"/>
                <Button Style="{StaticResource CalcButton}" Content="5" Click="Number_Click"/>
                <Button Style="{StaticResource CalcButton}" Content="6" Click="Number_Click"/>
                <Button Style="{StaticResource OperatorButton}" Content="-" Click="Operator_Click" Tag="-"/>

                <!-- Ряд 4 -->
                <Button Style="{StaticResource CalcButton}" Content="1" Click="Number_Click"/>
                <Button Style="{StaticResource CalcButton}" Content="2" Click="Number_Click"/>
                <Button Style="{StaticResource CalcButton}" Content="3" Click="Number_Click"/>
                <Button Style="{StaticResource OperatorButton}" Content="+" Click="Operator_Click" Tag="+"/>

                <!-- Ряд 5 -->
                <Button Style="{StaticResource CalcButton}" Content="0" Click="Number_Click" Grid.ColumnSpan="2"/>
                <Button Style="{StaticResource CalcButton}" Content="." Click="Decimal_Click"/>
                <Button Style="{StaticResource EqualsButton}" Content="=" Click="Equals_Click"/>
            </UniformGrid>
        </Grid>
    </Border>

    <Window.Resources>
        <!-- Базовый стиль кнопки -->
        <Style x:Key="CalcButton" TargetType="Button">
            <Setter Property="FontSize" Value="24"/>
            <Setter Property="FontWeight" Value="Medium"/>
            <Setter Property="Foreground" Value="White"/>
            <Setter Property="Background" Value="#33FFFFFF"/>
            <Setter Property="BorderThickness" Value="0"/>
            <Setter Property="Margin" Value="4"/>
            <Setter Property="Cursor" Value="Hand"/>
            <Setter Property="Template">
                <Setter.Value>
                    <ControlTemplate TargetType="Button">
                        <Border x:Name="border" CornerRadius="12" Background="{TemplateBinding Background}">
                            <ContentPresenter HorizontalAlignment="Center" VerticalAlignment="Center"/>
                        </Border>
                        <ControlTemplate.Triggers>
                            <Trigger Property="IsMouseOver" Value="True">
                                <Setter TargetName="border" Property="Background" Value="#4DFFFFFF"/>
                            </Trigger>
                            <Trigger Property="IsPressed" Value="True">
                                <Setter TargetName="border" Property="Background" Value="#66FFFFFF"/>
                            </Trigger>
                        </ControlTemplate.Triggers>
                    </ControlTemplate>
                </Setter.Value>
            </Setter>
        </Style>

        <!-- Стиль операторов (оранжевый акцент) -->
        <Style x:Key="OperatorButton" TargetType="Button" BasedOn="{StaticResource CalcButton}">
            <Setter Property="Background" Value="#FFFF9F0A"/>
            <Setter Property="Foreground" Value="Black"/>
            <Setter Property="FontWeight" Value="Bold"/>
            <Setter Property="Template">
                <Setter.Value>
                    <ControlTemplate TargetType="Button">
                        <Border x:Name="border" CornerRadius="12" Background="{TemplateBinding Background}">
                            <ContentPresenter HorizontalAlignment="Center" VerticalAlignment="Center"/>
                        </Border>
                        <ControlTemplate.Triggers>
                            <Trigger Property="IsMouseOver" Value="True">
                                <Setter TargetName="border" Property="Background" Value="#FFCC7A00"/>
                            </Trigger>
                        </ControlTemplate.Triggers>
                    </ControlTemplate>
                </Setter.Value>
            </Setter>
        </Style>

        <!-- Стиль кнопки равенства -->
        <Style x:Key="EqualsButton" TargetType="Button" BasedOn="{StaticResource OperatorButton}">
            <Setter Property="Background" Value="#FF32D74B"/>
            <Setter Property="Template">
                <Setter.Value>
                    <ControlTemplate TargetType="Button">
                        <Border x:Name="border" CornerRadius="12" Background="{TemplateBinding Background}">
                            <ContentPresenter HorizontalAlignment="Center" VerticalAlignment="Center"/>
                        </Border>
                        <ControlTemplate.Triggers>
                            <Trigger Property="IsMouseOver" Value="True">
                                <Setter TargetName="border" Property="Background" Value="#FF28B83E"/>
                            </Trigger>
                        </ControlTemplate.Triggers>
                    </ControlTemplate>
                </Setter.Value>
            </Setter>
        </Style>
    </Window.Resources>
</Window>
```

#### Шаг 3: Создайте файл `MainWindow.xaml.cs`
Логика калькулятора.

```csharp
using System.Windows;
using System.Windows.Controls;
using System.Windows.Input;

namespace BeautifulCalculator;

public partial class MainWindow : Window
{
    private double _currentValue = 0;
    private double _previousValue = 0;
    private string _currentOperator = "";
    private bool _isNewEntry = true;
    private bool _hasDecimal = false;

    public MainWindow()
    {
        InitializeComponent();
    }

    // Перетаскивание окна за любую область
    private void Window_MouseLeftButtonDown(object sender, MouseButtonEventArgs e) => DragMove();

    private void CloseButton_Click(object sender, RoutedEventArgs e) => Close();

    private void Number_Click(object sender, RoutedEventArgs e)
    {
        if (sender is not Button btn) return;

        if (_isNewEntry)
        {
            DisplayText.Text = btn.Content.ToString();
            _isNewEntry = false;
            _hasDecimal = false;
        }
        else
        {
            if (DisplayText.Text == "0") DisplayText.Text = "";
            DisplayText.Text += btn.Content;
        }
    }

    private void Decimal_Click(object sender, RoutedEventArgs e)
    {
        if (!_hasDecimal && !_isNewEntry)
        {
            DisplayText.Text += ".";
            _hasDecimal = true;
        }
        else if (_isNewEntry)
        {
            DisplayText.Text = "0.";
            _isNewEntry = false;
            _hasDecimal = true;
        }
    }

    private void Operator_Click(object sender, RoutedEventArgs e)
    {
        if (sender is not Button btn) return;

        if (!_isNewEntry && !string.IsNullOrEmpty(_currentOperator))
        {
            Calculate();
        }
        else
        {
            _previousValue = double.Parse(DisplayText.Text);
        }

        _currentOperator = btn.Tag?.ToString() ?? "";
        HistoryText.Text = $"{_previousValue} {btn.Content}";
        _isNewEntry = true;
    }

    private void Equals_Click(object sender, RoutedEventArgs e)
    {
        if (!string.IsNullOrEmpty(_currentOperator))
        {
            Calculate();
            _currentOperator = "";
            HistoryText.Text = "";
        }
    }

    private void Clear_Click(object sender, RoutedEventArgs e)
    {
        DisplayText.Text = "0";
        HistoryText.Text = "";
        _currentValue = 0;
        _previousValue = 0;
        _currentOperator = "";
        _isNewEntry = true;
        _hasDecimal = false;
    }

    private void Negate_Click(object sender, RoutedEventArgs e)
    {
        if (double.TryParse(DisplayText.Text, out double val))
        {
            DisplayText.Text = (-val).ToString();
        }
    }

    private void Percent_Click(object sender, RoutedEventArgs e)
    {
        if (double.TryParse(DisplayText.Text, out double val))
        {
            DisplayText.Text = (val / 100).ToString();
            _isNewEntry = true;
        }
    }

    private void Calculate()
    {
        if (!double.TryParse(DisplayText.Text, out _currentValue)) return;

        double result = _currentOperator switch
        {
            "+" => _previousValue + _currentValue,
            "-" => _previousValue - _currentValue,
            "*" => _previousValue * _currentValue,
            "/" => _currentValue != 0 ? _previousValue / _currentValue : 0,
            _ => _currentValue
        };

        // Форматируем результат, убирая лишние нули
        DisplayText.Text = result.ToString("G15"); 
        _previousValue = result;
        _isNewEntry = true;
        _hasDecimal = result != Math.Floor(result);
    }
}
```

